class Solution:
    def isPossible(self, n: int, edges: List[List[int]]) -> bool:
        deg = [0] * (n + 1)
        es = set()
        for a, b in edges:
            deg[a] += 1; deg[b] += 1
            es.add((min(a, b), max(a, b)))
        odd = [i for i in range(1, n + 1) if deg[i] & 1]
        def has(a, b):
            return (min(a, b), max(a, b)) in es
        if not odd:
            return True
        if len(odd) == 2:
            a, b = odd
            if not has(a, b):
                return True
            return any(c != a and c != b and deg[c] % 2 == 0
                       and not has(a, c) and not has(b, c)
                       for c in range(1, n + 1))
        if len(odd) == 4:
            a, b, c, d = odd
            return (not has(a, b) and not has(c, d)) or \
                   (not has(a, c) and not has(b, d)) or \
                   (not has(a, d) and not has(b, c))
        return False

