class Solution {
public:
    bool isPossible(int n, vector<vector<int>>& edges) {
        vector<int> deg(n + 1, 0);
        set<pair<int,int>> es;
        for (auto& e : edges) {
            deg[e[0]]++; deg[e[1]]++;
            es.insert({min(e[0], e[1]), max(e[0], e[1])});
        }
        vector<int> odd;
        for (int i = 1; i <= n; i++) if (deg[i] & 1) odd.push_back(i);
        auto has = [&](int a, int b) {
            return es.count({min(a, b), max(a, b)}) > 0;
        };
        if (odd.empty()) return true;
        if (odd.size() == 2) {
            int a = odd[0], b = odd[1];
            if (!has(a, b)) return true;
            for (int c = 1; c <= n; c++)
                if (c != a && c != b && deg[c] % 2 == 0 && !has(a, c) && !has(b, c))
                    return true;
            return false;
        }
        if (odd.size() == 4) {
            int a = odd[0], b = odd[1], c = odd[2], d = odd[3];
            return (!has(a, b) && !has(c, d)) || (!has(a, c) && !has(b, d)) || (!has(a, d) && !has(b, c));
        }
        return false;
    }
};

