class Solution {
    public boolean isPossible(int n, int[][] edges) {
        int[] deg = new int[n + 1];
        Set<Long> es = new HashSet<>();
        for (int[] e : edges) {
            deg[e[0]]++; deg[e[1]]++;
            int a = Math.min(e[0], e[1]), b = Math.max(e[0], e[1]);
            es.add((long) a * 100001L + b);
        }
        List<Integer> odd = new ArrayList<>();
        for (int i = 1; i <= n; i++) if ((deg[i] & 1) == 1) odd.add(i);
        if (odd.isEmpty()) return true;
        if (odd.size() == 2) {
            int a = odd.get(0), b = odd.get(1);
            if (!es.contains(key(a, b))) return true;
            for (int c = 1; c <= n; c++)
                if (c != a && c != b && deg[c] % 2 == 0
                        && !es.contains(key(a, c)) && !es.contains(key(b, c)))
                    return true;
            return false;
        }
        if (odd.size() == 4) {
            int a = odd.get(0), b = odd.get(1), c = odd.get(2), d = odd.get(3);
            return (!es.contains(key(a, b)) && !es.contains(key(c, d)))
                || (!es.contains(key(a, c)) && !es.contains(key(b, d)))
                || (!es.contains(key(a, d)) && !es.contains(key(b, c)));
        }
        return false;
    }
    private long key(int a, int b) {
        int lo = Math.min(a, b), hi = Math.max(a, b);
        return (long) lo * 100001L + hi;
    }
}

