var isPossible = function(n, edges) {
    const deg = new Array(n + 1).fill(0);
    const es = new Set();
    for (const [a, b] of edges) {
        deg[a]++; deg[b]++;
        es.add(Math.min(a, b) * 100001 + Math.max(a, b));
    }
    const odd = [];
    for (let i = 1; i <= n; i++) if (deg[i] & 1) odd.push(i);
    const has = (a, b) => es.has(Math.min(a, b) * 100001 + Math.max(a, b));
    if (odd.length === 0) return true;
    if (odd.length === 2) {
        const [a, b] = odd;
        if (!has(a, b)) return true;
        for (let c = 1; c <= n; c++)
            if (c !== a && c !== b && deg[c] % 2 === 0 && !has(a, c) && !has(b, c))
                return true;
        return false;
    }
    if (odd.length === 4) {
        const [a, b, c, d] = odd;
        return (!has(a, b) && !has(c, d)) || (!has(a, c) && !has(b, d)) || (!has(a, d) && !has(b, c));
    }
    return false;
};
